//import { initialState } from '../store/configureStore';
//import { fetchAuth } from '../actions/authActions'

import axios from 'axios';

export function fetchMessages(messageType) {

    return (dispatch, getState) => {

    console.log('fetch messages');
    
        //let messagesSearchUrlNoSlash = getState().messagesSearchUrl.replace(/\/+$/, "");
        
        axios.get('https://scbm.amfdev.co.uk/api/message/')
        .then(json => catchFetchMessagesNoResults(json.data, dispatch, messageType))
        .then(json => catchFetchMessagesOtherError(json, dispatch, messageType))
        .then(json => doFetchMessagesSuccess(json, dispatch, messageType))
        .catch(error => {

                if (error.response) {   
                      dispatch({
                          type: "FETCH_MESSAGES_UNKNOWN_ERROR",
                          messageType: messageType
                      })  
                }
        });
                  
    }
    

}

function catchFetchMessagesNoResults(json, dispatch, messageType) {
    console.log('catchSentMessagesSearchNoResults')
    console.log(json);
    if (json.noResults) {
        dispatch({
                type: "FETCH_MESSAGES_NO_RESULTS",
                messageType: messageType
              })
    
        throw Error(json.error);
                
    }
    
  return json;
}


function catchFetchMessagesOtherError(json, dispatch, messageType) {
    console.log('catchSentMessagesSearchOtherError')
    if (!json.success) {
        dispatch({
                type: "FETCH_MESSAGES_OTHER_ERROR",
                messageType: messageType
              })
        throw Error(json.error);
    }
    
  return json;
}


function doFetchMessagesSuccess(json, dispatch, messageType) {
    console.log('doMessagesSearchSuccess')
 
        if (messageType === 'sent') {
    
        dispatch({
                type: "FETCH_SENT_MESSAGES_RESULT",
                messageData: json.messageData
              });
        } else if (messageType === 'recevied') {
    
            dispatch({
                type: "FETCH_RECEIVED_MESSAGES_RESULT",
                messageData: json.messageData
              });
        }
          
            /*dispatch({ type: "SUCCESS_ALERT_SHOW" });
            
            window.setTimeout(()=>{ 
            dispatch({ type: "SUCCESS_ALERT_HIDE" });
            },4000)*/
               
  return json;
}


export function handleMessagesSelectedRowsChange(selectedMessages, messageType) {
   
    return (dispatch, getState) => {
  
    if (messageType === "sent") {

            //console.log('dispatch rows change selected messages')
                dispatch({
                    type: "SENT_MESSAGES_SELECTED_ROWS_CHANGE",
                    selectedSentMessages: selectedMessages
                })
           
            if(getState().selectedSentMessages && getState().selectedSentMessages.length > 0) {
                console.log('yes selected messages more than 0')
                //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'block';
                dispatch({
                    type: "SENT_MESSAGES_MESSAGE_FORM_SHOW"
                })
            } else {
                //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'none';
                dispatch({
                    type: "SENT_MESSAGES_MESSAGE_FORM_HIDE"
              })
            }
            
        }
    
    }
           
}

export function handleMessageChange(event, messageType) {
    
    return (dispatch, getState) => {
        
        if (messageType === "sent") {
        
            const { value } = event.target
      
                dispatch({
                    type: "SENT_MESSAGES_MESSAGE_CHANGE",
                    sentMessagesMessage: value
                })
           
            if(getState().sentMessagesMessage && getState().sentMessagesMessage.length > 10) {
                dispatch({
                    type: "SENT_MESSAGES_MESSAGE_SUBMIT_ENABLE"
              })
            } else {
                dispatch({
                    type: "SENT_MESSAGES_MESSAGE_SUBMIT_DISABLE"
              })
            }
            
        }

          
    }
    
}


export function handleMessageSubmit(messageType) {
    
    return (dispatch, getState) => {

        if (messageType === "sent") {
            
            dispatch({
             type: "MESSAGE_SUBMITTED"
           });
               
            axios({
            method: 'post',
            url: 'https://scbm.amfdev.co.uk/api/message/',
            headers: {}, 
            data: {
                selectedProfiles: getState().eval("selectedSentMessages"),
                message: getState().sentMessagesMessage,
                searchUrl: getState().scProfile                     
            }
            })    
            .then(json => catchMessageError(json.data, dispatch))
            .then(json => dispatch(doMessageSuccess(json, dispatch, getState, "sent")))
            .catch(error => {
    
                    if (error.response) {   
                          dispatch({
                              type: "MESSAGE_UNKNOWN_ERROR"
                          })  
                    }
            });
            
        }
                  
    }
    
}


function catchMessageError(json, dispatch) {
    //console.log('catchFollowersMessageError')
    console.log(json)
    if (!json.success) {
        dispatch({
                type: "MESSAGE_ERROR"
              })
        throw Error(json.error);
    }
    
  return json;
}


function doMessageSuccess(json, dispatch, getState, messageType) {
    
    return (dispatch, getState) => {
        
            let successArray = [];
            
                for (let sendResult of json.result) {
         
                  const elementsIndex = getState().sentMessageData.findIndex(element => element.profileUrl === sendResult.profileUrl );
                   
                   let newArray = [...getState().sentMessageData]
                  
                    newArray[elementsIndex] = {...newArray[elementsIndex], messaged: sendResult.messageResult}
             
                        //await console.log(newArray);
                       
                           dispatch({
                             type: "MESSAGE_RESULT",
                             sentMessageData: newArray
                           })
                               
                        
                          if (sendResult.messageResult === 'Success') {
                             successArray.push(sendResult.profileUrl);
                          }
                                 
                   
                }
              
                dispatch(fetchMessages());
                        
                if(successArray.length > 0) {
                    
                    dispatch({ type: "SUCCESS_ALERT_SET_TEXT", text: "Message sent to " + successArray.length + " users." });
                
                    dispatch({ type: "SUCCESS_ALERT_SHOW" });
                    
                    window.setTimeout(()=>{ 
                    dispatch({ type: "SUCCESS_ALERT_HIDE" });
                    },4000)
                    
                } else {
           
                    dispatch({ type: "ERROR_ALERT_SET_TEXT", text: "Message not sent! Something went wrong." });
                
                    dispatch({ type: "ERROR_ALERT_SHOW" });
                    
                    window.setTimeout(()=>{ 
                    dispatch({ type: "ERROR_ALERT_HIDE" });
                    },4000)
                  
                }
                //return { newArray, successArray };
     
    }
    
}
